import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int stride, int padding, int output_padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
#define MAX_COUT 128
__global__ void __launch_bounds__(256, 4) conv_transpose3d_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int Cin, int Din, int Hin, int Win,
    int Cout, int Dout, int Hout, int Wout,
    int K, int stride, int padding, int dilation, int groups)
{
    const int TD = 4, TH = 8, TW = 8;
    const int Cin_per_group  = Cin / groups;
    const int Cout_per_group = Cout / groups;
    const int D_tiles = (Dout + TD - 1) / TD;
    const int d_tile  = blockIdx.z % D_tiles;
    const int n       = blockIdx.z / D_tiles;
    const int tz = threadIdx.z;
    const int ty = threadIdx.y;
    const int tx = threadIdx.x;
    const int od = d_tile * TD + tz;
    const int oh = blockIdx.y * TH + ty;
    const int ow = blockIdx.x * TW + tx;
    const bool out_valid = (od < Dout && oh < Hout && ow < Wout);
    const int64_t sXn = (int64_t)Cin * Din * Hin * Win;
    const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
    const float* Xn = X + (int64_t)n * sXn;
    float*       Yn = Y + (int64_t)n * sYn;
    // CuTe global tensors
    auto mX = make_tensor(
        make_gmem_ptr(Xn),
        make_shape(Cin, Din, Hin, Win),
        make_stride((int64_t)Din * Hin * Win, (int64_t)Hin * Win, (int64_t)Win, Int<1>{})
    );
    auto mY = make_tensor(
        make_gmem_ptr(Yn),
        make_shape(Cout, Dout, Hout, Wout),
        make_stride((int64_t)Dout * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, Int<1>{})
    );
    auto mW = make_tensor(
        make_gmem_ptr(W),
        make_shape(Cin, Cout_per_group, K, K, K),
        make_stride((int64_t)Cout_per_group * K * K * K, (int64_t)K * K * K, (int64_t)K * K, (int64_t)K, Int<1>{})
    );
    extern __shared__ float sW_raw[];
    auto sW = make_tensor(
        make_smem_ptr(sW_raw),
        make_shape(Cin_per_group, Cout_per_group),
        make_stride(Cout_per_group, Int<1>{})
    );
    const int tid = tz * (TH * TW) + ty * TW + tx;
    const int total_threads = TD * TH * TW;
    const int flatWeightSize = Cin_per_group * Cout_per_group;
    float acc[MAX_COUT];
    #pragma unroll
    for (int co = 0; co < MAX_COUT; ++co) acc[co] = 0.0f;
    for (int g = 0; g < groups; ++g) {
        const int ci_start = g * Cin_per_group;
        const int co_start = g * Cout_per_group;
        for (int kd = 0; kd < K; ++kd) {
            for (int kh = 0; kh < K; ++kh) {
                for (int kw = 0; kw < K; ++kw) {
                    bool valid = out_valid;
                    int id = 0, ih = 0, iw = 0;
                    if (valid) {
                        int idn = od + padding - kd * dilation;
                        int ihn = oh + padding - kh * dilation;
                        int iwn = ow + padding - kw * dilation;
                        bool mod_ok = ((idn % stride) == 0) && ((ihn % stride) == 0) && ((iwn % stride) == 0);
                        if (mod_ok) {
                            id = idn / stride;
                            ih = ihn / stride;
                            iw = iwn / stride;
                            valid = (id >= 0 && id < Din) && (ih >= 0 && ih < Hin) && (iw >= 0 && iw < Win);
                        } else {
                            valid = false;
                        }
                    }
                    // Cooperative load of weight slice for this (kd,kh,kw,g) into shared memory
                    for (int idx = tid; idx < flatWeightSize; idx += total_threads) {
                        int ci_local = idx / Cout_per_group;
                        int co_local = idx % Cout_per_group;
                        int ci = ci_start + ci_local;
                        sW(ci_local, co_local) = mW(ci, co_local, kd, kh, kw);
                    }
                    __syncthreads();
                    if (valid) {
                        for (int ci_local = 0; ci_local < Cin_per_group; ++ci_local) {
                            int ci = ci_start + ci_local;
                            float xval = mX(ci, id, ih, iw);
                            #pragma unroll 4
                            for (int co_local = 0; co_local < Cout_per_group; ++co_local) {
                                acc[co_start + co_local] += xval * sW(ci_local, co_local);
                            }
                        }
                    }
                    __syncthreads();
                }
            }
        }
    }
    if (out_valid) {
        for (int co = 0; co < Cout; ++co) {
            float val = acc[co];
            if (Bias != nullptr) val += Bias[co];
            mY(co, od, oh, ow) = val;
        }
    }
}
// ---------------------------------------------------------------------------
// Register-blocked fast path specialized for groups == 1.
// Cout is a compile-time template parameter here, so the channel-accumulation
// loop has a fully known trip count and can be completely unrolled. This lets
// the compiler keep the whole accumulator in registers (SROA) instead of
// spilling the runtime-indexed acc[] array of the generic kernel above into
// local memory, which was the dominant source of memory-pipe traffic.
// ---------------------------------------------------------------------------
template <int COUT>
__global__ void __launch_bounds__(256, 6) conv_transpose3d_kernel_g1(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int Cin, int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int K, int stride, int padding, int dilation)
{
    const int TD = 4, TH = 8, TW = 8;
    const int D_tiles = (Dout + TD - 1) / TD;
    const int d_tile  = blockIdx.z % D_tiles;
    const int n       = blockIdx.z / D_tiles;
    const int tz = threadIdx.z;
    const int ty = threadIdx.y;
    const int tx = threadIdx.x;
    const int od = d_tile * TD + tz;
    const int oh = blockIdx.y * TH + ty;
    const int ow = blockIdx.x * TW + tx;
    const bool out_valid = (od < Dout && oh < Hout && ow < Wout);
    const int64_t sXn = (int64_t)Cin * Din * Hin * Win;
    const int64_t sYn = (int64_t)COUT * Dout * Hout * Wout;
    const float* Xn = X + (int64_t)n * sXn;
    float*       Yn = Y + (int64_t)n * sYn;
    auto mX = make_tensor(
        make_gmem_ptr(Xn),
        make_shape(Cin, Din, Hin, Win),
        make_stride((int64_t)Din * Hin * Win, (int64_t)Hin * Win, (int64_t)Win, Int<1>{})
    );
    auto mY = make_tensor(
        make_gmem_ptr(Yn),
        make_shape(Int<COUT>{}, Dout, Hout, Wout),
        make_stride((int64_t)Dout * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, Int<1>{})
    );
    auto mW = make_tensor(
        make_gmem_ptr(W),
        make_shape(Cin, Int<COUT>{}, K, K, K),
        make_stride((int64_t)COUT * K * K * K, (int64_t)K * K * K, (int64_t)K * K, (int64_t)K, Int<1>{})
    );
    extern __shared__ float sW_raw[];
    auto sW = make_tensor(
        make_smem_ptr(sW_raw),
        make_shape(Cin, Int<COUT>{}),
        make_stride(Int<COUT>{}, Int<1>{})
    );
    const int tid = tz * (TH * TW) + ty * TW + tx;
    const int total_threads = TD * TH * TW;
    const int flatWeightSize = Cin * COUT;
    float acc[COUT];
    #pragma unroll
    for (int co = 0; co < COUT; ++co) acc[co] = 0.0f;
    for (int kd = 0; kd < K; ++kd) {
        for (int kh = 0; kh < K; ++kh) {
            for (int kw = 0; kw < K; ++kw) {
                bool valid = out_valid;
                int id = 0, ih = 0, iw = 0;
                if (valid) {
                    int idn = od + padding - kd * dilation;
                    int ihn = oh + padding - kh * dilation;
                    int iwn = ow + padding - kw * dilation;
                    bool mod_ok = ((idn % stride) == 0) && ((ihn % stride) == 0) && ((iwn % stride) == 0);
                    if (mod_ok) {
                        id = idn / stride;
                        ih = ihn / stride;
                        iw = iwn / stride;
                        valid = (id >= 0 && id < Din) && (ih >= 0 && ih < Hin) && (iw >= 0 && iw < Win);
                    } else {
                        valid = false;
                    }
                }
                for (int idx = tid; idx < flatWeightSize; idx += total_threads) {
                    int ci = idx / COUT;
                    int co = idx % COUT;
                    sW(ci, co) = mW(ci, co, kd, kh, kw);
                }
                __syncthreads();
                if (valid) {
                    for (int ci = 0; ci < Cin; ++ci) {
                        float xval = mX(ci, id, ih, iw);
                        #pragma unroll
                        for (int co = 0; co < COUT; ++co) {
                            acc[co] += xval * sW(ci, co);
                        }
                    }
                }
                __syncthreads();
            }
        }
    }
    if (out_valid) {
        #pragma unroll
        for (int co = 0; co < COUT; ++co) {
            float val = acc[co];
            if (Bias != nullptr) val += Bias[co];
            mY(co, od, oh, ow) = val;
        }
    }
}
template <int COUT>
__global__ void __launch_bounds__(256, 4) conv_transpose3d_kernel_g1_s1(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int Cin, int Din, int Hin, int Win,
    int Dout, int Hout, int Wout,
    int K, int padding, int dilation)
{
    const int TD = 4, TH = 8, TW = 8;
    const int RW = 2; // must match register-blocking factor at kernel launch site (reduced for occupancy)
    const int D_tiles = (Dout + TD - 1) / TD;
    const int d_tile  = blockIdx.z % D_tiles;
    const int n       = blockIdx.z / D_tiles;
    const int tz = threadIdx.z;
    const int ty = threadIdx.y;
    const int tx = threadIdx.x;
    const int od0 = d_tile * TD;
    const int oh0 = blockIdx.y * TH;
    const int ow0 = blockIdx.x * (TW * RW);
    const int od = od0 + tz;
    const int oh = oh0 + ty;
    int ow[RW];
    bool out_valid[RW];
    #pragma unroll
    for (int r = 0; r < RW; ++r) ow[r] = ow0 + tx + r * TW;
    const bool dh_valid = (od < Dout && oh < Hout);
    #pragma unroll
    for (int r = 0; r < RW; ++r) out_valid[r] = dh_valid && (ow[r] < Wout);
    const int64_t sXn = (int64_t)Cin * Din * Hin * Win;
    const int64_t sYn = (int64_t)COUT * Dout * Hout * Wout;
    const float* Xn = X + (int64_t)n * sXn;
    float*       Yn = Y + (int64_t)n * sYn;
    const int KKK = K * K * K;
    const int ID_TILE = TD + (K - 1) * dilation;
    const int IH_TILE = TH + (K - 1) * dilation;
    const int IW_TILE = TW * RW + (K - 1) * dilation;
    const int id_min = od0 + padding - (K - 1) * dilation;
    const int ih_min = oh0 + padding - (K - 1) * dilation;
    const int iw_min = ow0 + padding - (K - 1) * dilation;
    extern __shared__ float smem[];
    const int wtotal = COUT * KKK;
    float* sW = smem;
    float* sX = smem + wtotal;
    const int tid = tz * (TH * TW) + ty * TW + tx;
    const int total_threads = TD * TH * TW;
    const int xtotal = ID_TILE * IH_TILE * IW_TILE;
    float acc[RW][COUT];
    #pragma unroll
    for (int r = 0; r < RW; ++r) {
        #pragma unroll
        for (int co = 0; co < COUT; ++co) acc[r][co] = 0.0f;
    }
    for (int ci = 0; ci < Cin; ++ci) {
        const float* Wci = W + (int64_t)ci * COUT * KKK;
        for (int idx = tid; idx < wtotal; idx += total_threads) {
            sW[idx] = Wci[idx];
        }
        const float* Xci = Xn + (int64_t)ci * Din * Hin * Win;
        for (int idx = tid; idx < xtotal; idx += total_threads) {
            int iw_l = idx % IW_TILE;
            int rem  = idx / IW_TILE;
            int ih_l = rem % IH_TILE;
            int id_l = rem / IH_TILE;
            int id = id_min + id_l;
            int ih = ih_min + ih_l;
            int iw = iw_min + iw_l;
            float v = 0.0f;
            if (id >= 0 && id < Din && ih >= 0 && ih < Hin && iw >= 0 && iw < Win) {
                v = Xci[((int64_t)id * Hin + ih) * Win + iw];
            }
            sX[idx] = v;
        }
        __syncthreads();
        if (dh_valid) {
            for (int kd = 0; kd < K; ++kd) {
                int id_l = od + padding - kd * dilation - id_min;
                for (int kh = 0; kh < K; ++kh) {
                    int ih_l = oh + padding - kh * dilation - ih_min;
                    const float* sXrow = sX + (int64_t)(id_l * IH_TILE + ih_l) * IW_TILE;
                    for (int kw = 0; kw < K; ++kw) {
                        int kw_off = padding - kw * dilation - iw_min;
                        float xval[RW];
                        #pragma unroll
                        for (int r = 0; r < RW; ++r) {
                            xval[r] = sXrow[ow[r] + kw_off];
                        }
                        int kidx = (kd * K + kh) * K + kw;
                        #pragma unroll
                        for (int co = 0; co < COUT; ++co) {
                            float wv = sW[co * KKK + kidx];
                            #pragma unroll
                            for (int r = 0; r < RW; ++r) {
                                acc[r][co] += xval[r] * wv;
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    bool any_valid = false;
    #pragma unroll
    for (int r = 0; r < RW; ++r) any_valid = any_valid || out_valid[r];
    if (any_valid) {
        const int64_t coStride = (int64_t)Dout * Hout * Wout;
        int64_t base[RW];
        #pragma unroll
        for (int r = 0; r < RW; ++r) base[r] = (int64_t)od * Hout * Wout + (int64_t)oh * Wout + ow[r];
        #pragma unroll
        for (int co = 0; co < COUT; ++co) {
            #pragma unroll
            for (int r = 0; r < RW; ++r) {
                if (out_valid[r]) {
                    float val = acc[r][co];
                    if (Bias != nullptr) val += Bias[co];
                    Yn[(int64_t)co * coStride + base[r]] = val;
                }
            }
        }
    }
}
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int stride, int padding, int output_padding, int dilation, int groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "x must be [N,C,D,H,W]");
    TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, K, K, K]");
    if (bias.has_value()) {
        TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");
    }
    int64_t N   = x.size(0);
    int64_t Cin = x.size(1);
    int64_t Din = x.size(2);
    int64_t Hin = x.size(3);
    int64_t Win = x.size(4);
    int64_t Cout_per_group = weight.size(1);
    int64_t K = weight.size(2);
    TORCH_CHECK(weight.size(0) == Cin, "weight.size(0) must equal Cin");
    TORCH_CHECK(weight.size(3) == K && weight.size(4) == K, "kernel must be cubic");
    int64_t Cout = Cout_per_group * groups;
    TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
    TORCH_CHECK(Cout <= MAX_COUT, "Cout exceeds kernel MAX_COUT limit");
    int64_t Dout = (Din - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int64_t Hout = (Hin - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int64_t Wout = (Win - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (bias.has_value()) {
        b_c = bias.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
        b_ptr = b_c.data_ptr<float>();
    }
    auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());
    const int TD = 4, TH = 8, TW = 8;
    int D_tiles = (int)((Dout + TD - 1) / TD);
    dim3 block(TW, TH, TD);
    dim3 grid(
        (unsigned)((Wout + TW - 1) / TW),
        (unsigned)((Hout + TH - 1) / TH),
        (unsigned)(N * D_tiles)
    );
    int Cin_per_group = (int)(Cin / groups);
    size_t shmem_bytes = (size_t)Cin_per_group * (size_t)Cout_per_group * sizeof(float);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    bool launched = false;
    if (groups == 1 && stride == 1) {
        const int RW = 2; // must match register-blocking factor in conv_transpose3d_kernel_g1_s1
        int ID_TILE = TD + (int)((K - 1) * dilation);
        int IH_TILE = TH + (int)((K - 1) * dilation);
        int IW_TILE = TW * RW + (int)((K - 1) * dilation);
        size_t xtile_elems = (size_t)ID_TILE * (size_t)IH_TILE * (size_t)IW_TILE;
        dim3 grid_s1(
            (unsigned)((Wout + (TW * RW) - 1) / (TW * RW)),
            (unsigned)((Hout + TH - 1) / TH),
            (unsigned)(N * D_tiles)
        );
        #define DISPATCH_COUT_S1(CV)                                                          \
            {                                                                                  \
                size_t wtile_elems = (size_t)CV * (size_t)K * (size_t)K * (size_t)K;           \
                size_t shmem_bytes_s1 = (wtile_elems + xtile_elems) * sizeof(float);            \
                conv_transpose3d_kernel_g1_s1<CV><<<grid_s1, block, shmem_bytes_s1, stream>>>(  \
                    x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),   \
                    (int)N, (int)Cin, (int)Din, (int)Hin, (int)Win,                            \
                    (int)Dout, (int)Hout, (int)Wout,                                           \
                    (int)K, padding, dilation);                                                \
                launched = true;                                                                \
            }
        switch ((int)Cout) {
            case 8:   DISPATCH_COUT_S1(8);   break;
            case 16:  DISPATCH_COUT_S1(16);  break;
            case 24:  DISPATCH_COUT_S1(24);  break;
            case 32:  DISPATCH_COUT_S1(32);  break;
            case 48:  DISPATCH_COUT_S1(48);  break;
            case 64:  DISPATCH_COUT_S1(64);  break;
            case 96:  DISPATCH_COUT_S1(96);  break;
            case 128: DISPATCH_COUT_S1(128); break;
            default: break;
        }
        #undef DISPATCH_COUT_S1
    }
    if (!launched && groups == 1) {
        #define DISPATCH_COUT(CV)                                                     \
            conv_transpose3d_kernel_g1<CV><<<grid, block, shmem_bytes, stream>>>(        \
                x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(), \
                (int)N, (int)Cin, (int)Din, (int)Hin, (int)Win,                          \
                (int)Dout, (int)Hout, (int)Wout,                                         \
                (int)K, stride, padding, dilation);                                      \
            launched = true;
        switch ((int)Cout) {
            case 8:   DISPATCH_COUT(8);   break;
            case 16:  DISPATCH_COUT(16);  break;
            case 24:  DISPATCH_COUT(24);  break;
            case 32:  DISPATCH_COUT(32);  break;
            case 48:  DISPATCH_COUT(48);  break;
            case 64:  DISPATCH_COUT(64);  break;
            case 96:  DISPATCH_COUT(96);  break;
            case 128: DISPATCH_COUT(128); break;
            default: break;
        }
        #undef DISPATCH_COUT
    }
    if (!launched) {
        conv_transpose3d_kernel<<<grid, block, shmem_bytes, stream>>>(
            x_c.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_ptr,
            y.data_ptr<float>(),
            (int)N, (int)Cin, (int)Din, (int)Hin, (int)Win,
            (int)Cout, (int)Dout, (int)Hout, (int)Wout,
            (int)K, stride, padding, dilation, groups
        );
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with a cubic kernel, implemented via a custom
    cooperative-tiled CUDA kernel that uses CuTe tensors for indexing and
    shared-memory caching of the per-kernel-offset weight slice.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        Cin = self.in_channels
