                    if (Bias != nullptr) val += Bias[co];
                    Yn[(int64_t)co * coStride + base[r]] = val;
                }
            }
        }
    }
}
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int stride, int padding, int output_padding, int dilation, int groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "x must be [N,C,D,H,W]");
    TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, K, K, K]");
    if (bias.has_value()) {
        TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");
    }
    int64_t N   = x.size(0);
    int64_t Cin = x.size(1);
    int64_t Din = x.size(2);
    int64_t Hin = x.size(3);
    int64_t Win = x.size(4);
    int64_t Cout_per_group = weight.size(1);
    int64_t K = weight.size(2);
    TORCH_CHECK(weight.size(0) == Cin, "weight.size(0) must equal Cin");
    TORCH_CHECK(weight.size(3) == K && weight.size(4) == K, "kernel must be cubic");
    int64_t Cout = Cout_per_group * groups;
    TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
    TORCH_CHECK(Cout <= MAX_COUT, "Cout exceeds kernel MAX_COUT limit");
    int64_t Dout = (Din - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int64_t Hout = (Hin - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int64_t Wout = (Win - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (bias.has_value()) {
        b_c = bias.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
        b_ptr = b_c.data_ptr<float>();
    }
    auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());
    const int TD = 4, TH = 8, TW = 8;
    int D_tiles = (int)((Dout + TD - 1) / TD);
    dim3 block(TW, TH, TD);
    dim3 grid(
        (unsigned)((Wout + TW - 1) / TW),
        (unsigned)((Hout + TH - 1) / TH),
        (unsigned)(N * D_tiles)
    );
    int Cin_per_group = (int)(Cin / groups);
    size_t shmem_bytes = (size_t)Cin_per_group * (size_t)Cout_per_group * sizeof(float);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    bool launched = false;
    if (groups == 1 && stride == 1) {
        const int RW = 4; // must match register-blocking factor in conv_transpose3d_kernel_g1_s1
        int ID_TILE = TD + (int)((K - 1) * dilation);
        int IH_TILE = TH + (int)((K - 1) * dilation);
        int IW_TILE = TW * RW + (int)((K - 1) * dilation);
        size_t xtile_elems = (size_t)ID_TILE * (size_t)IH_TILE * (size_t)IW_TILE;
        dim3 grid_s1(
            (unsigned)((Wout + (TW * RW) - 1) / (TW * RW)),
            (unsigned)((Hout + TH - 1) / TH),
            (unsigned)(N * D_tiles)
        );
        #define DISPATCH_COUT_S1(CV)                                                          \
            {                                                                                  \
                size_t wtile_elems = (size_t)CV * (size_t)K * (size_t)K * (size_t)K;           \
                size_t shmem_bytes_s1 = (wtile_elems + xtile_elems) * sizeof(float);            \
                conv_transpose3d_kernel_g1_s1<CV><<<grid_s1, block, shmem_bytes_s1, stream>>>(  \
                    x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),   \
                    (int)N, (int)Cin, (int)Din, (int)Hin, (int)Win,                            \
                    (int)Dout, (int)Hout, (int)Wout,                                           \
                    (int)K, padding, dilation);                                                \
                launched = true;                                                                \
            }
        switch ((int)Cout) {
            case 8:   DISPATCH_COUT_S1(8);   break;
            case 16:  DISPATCH_COUT_S1(16);  break;
            case 24:  DISPATCH_COUT_S1(24);  break;
            case 32:  DISPATCH_COUT_S1(32);  break;
            case 48:  DISPATCH_COUT_S1(48);  break;
            case 64:  DISPATCH_COUT_S1(64);  break;
            case 96:  DISPATCH_COUT_S1(96);  break;
            case 128: DISPATCH_COUT_S1(128); break;
            default: break;
        }
        #undef DISPATCH_COUT_S1
    }
    if (!launched && groups == 1) {
        #define DISPATCH_COUT(CV)                                                     \
            conv_transpose3d_kernel_g1<CV><<<grid, block, shmem_bytes, stream>>>(        \
                x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(), \
                (int)N, (int)Cin, (int)Din, (int)Hin, (int)Win,                          \
                (int)Dout, (int)Hout, (int)Wout,                                         \
                (int)K, stride, padding, dilation);                                      \
            launched = true;
        switch ((int)Cout) {
            case 8:   DISPATCH_COUT(8);   break;
            case 16:  DISPATCH_COUT(16);  break;
            case 24:  DISPATCH_COUT(24);  break;
            case 32:  DISPATCH_COUT(32);  break;
            case 48:  DISPATCH_COUT(48);  break;
            case 64:  DISPATCH_COUT(64);  break;
            case 96:  DISPATCH_COUT(96);  break;
            case 128: DISPATCH_COUT(128); break;
            default: break;
        }
        #undef DISPATCH_COUT
    }
    if (!launched) {
        conv_transpose3d_kernel<<<grid, block, shmem_bytes, stream>>>(
            x_c.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_ptr,
            y.data_ptr<float>(),
            (int)N, (int)Cin, (int)Din, (int)Hin, (int)Win,
            (int)Cout, (int)Dout, (int)Hout, (int)Wout,
            (int)K, stride, padding, dilation, groups
        );
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));
